#!/usr/bin/env python3
"""Génère les exercices faits main de Slovingo-sk-fr-children (usage : python3 tools/gen_exercises.py exercises).

Chaque exercice reprend mot pour mot une paire d'une fiche. Les distracteurs en slovaque
ne viennent que de ce qui a déjà été vu (intro 1 -> 5, puis Kit 1 -> 4)."""
import json, re, os, sys

OUT = sys.argv[1]
os.makedirs(OUT, exist_ok=True)


def slug(s):
    return re.sub(r'[^a-z0-9]+', '-', s.lower()).strip('-')


class Sheet:
    def __init__(self, name, sync="full"):
        self.name, self.sync, self.ex, self.ids = name, sync, [], set()

    def _id(self, t, key):
        base = f"{t}-{slug(key)}"
        i, n = base, 2
        while i in self.ids:
            i, n = f"{base}-{n}", n + 1
        self.ids.add(i)
        return i

    def qcm(self, l1, l2, c1, c2):
        self.ex.append(dict(id=self._id("qcm", l2), type="qcm", l1=l1, l2=l2, choices_l1=c1, choices_l2=c2))

    def listen(self, l1, l2, c1):
        self.ex.append(dict(id=self._id("listen", l2), type="listen", l1=l1, l2=l2, choices_l1=c1))

    def blank(self, l1, l2, m1, i1, m2, i2, c1, c2):
        self.ex.append(dict(id=self._id("blank", l2), type="fill-blank", l1=l1, l2=l2, missing_l1=m1, missing_l2=m2,
                            blank_index_l1=i1, blank_index_l2=i2, choices_l1=c1, choices_l2=c2, show_translation=True))

    def ab(self, l1, l2, m1, m2, c1, c2):
        def idx(t, m):
            for i, w in enumerate(t.split()):
                if w.strip('.,!?;:') == m:
                    return i
            raise SystemExit(f"blank introuvable: {m!r} dans {t!r}")
        self.blank(l1, l2, m1, idx(l1, m1), m2, idx(l2, m2), c1, c2)

    def order(self, l1, l2, t1, t2):
        self.ex.append(dict(id=self._id("order", l2), type="order", l1=l1, l2=l2, tokens_l1=t1, tokens_l2=t2))

    def match(self, L1, L2):
        self.ex.append(dict(id=self._id("match", L2[0]), type="match", l1=L1, l2=L2))

    def write(self):
        d = {"mode": "replace", "sync": self.sync, "exercises": self.ex}
        with open(os.path.join(OUT, self.name + ".exercises.json"), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
            f.write("\n")
        print(self.name, len(self.ex))


